-- Reduz drasticamente o texto dos sms_templates para diminuir custo Comtele.
-- Remove emojis (nao-GSM7 dobram custo), URLs longas e formatacoes. NAO altera templates Meta WhatsApp.
UPDATE public.sms_templates SET body = CASE name
